CREATE POLICY "Bilateral session visibility" ON public.workout_sessions AS RESTRICTIVE FOR SELECT TO authenticated USING(safety_visible(user_id));
CREATE FUNCTION public.crew_workout_status() RETURNS TABLE(id uuid,group_id uuid,user_id uuid,started_at timestamptz,status text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT id,group_id,user_id,started_at,status FROM workout_sessions WHERE is_group_member(group_id,auth.uid()) $$;
REVOKE ALL ON FUNCTION public.crew_workout_status() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.crew_workout_status() TO authenticated;
CREATE OR REPLACE FUNCTION public.plan_tags_for_check_ins(_check_in_ids uuid[]) RETURNS TABLE(check_in_id uuid,plan_name text,plan_slug text,week integer,day_number integer) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT l.check_in_id,p.name,p.slug,l.week,l.day_number FROM plan_workout_logs l JOIN user_plans up ON up.id=l.user_plan_id JOIN plans p ON p.id=up.plan_id JOIN check_ins ci ON ci.id=l.check_in_id WHERE l.check_in_id=ANY(_check_in_ids) AND auth.uid() IS NOT NULL AND is_group_member(ci.group_id,auth.uid()) AND safety_visible(ci.user_id) $$;
CREATE OR REPLACE FUNCTION public.workout_summaries_for_check_ins(_check_in_ids uuid[]) RETURNS TABLE(check_in_id uuid,session_id uuid,title text,summary jsonb) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT c.id,ws.id,ws.title,ws.summary FROM check_ins c JOIN workout_sessions ws ON ws.check_in_ids @> ARRAY[c.id] AND ws.user_id=c.user_id WHERE c.id=ANY(_check_in_ids) AND ws.logged_at IS NOT NULL AND is_group_member(c.group_id,auth.uid()) AND safety_visible(c.user_id) $$;
CREATE OR REPLACE FUNCTION public.workout_detail_for_check_in(_check_in_id uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('title',ws.title,'summary',ws.summary,'sessionId',ws.id,'userId',c.user_id,'checkinDate',c.checkin_date,'sets',COALESCE((SELECT jsonb_agg(jsonb_build_object('exerciseId',l.exercise_id,'name',e.name,'imageStart',e.image_start,'logType',e.log_type,'equipment',e.equipment,'position',l.position,'setNo',l.set_no,'weight',l.weight,'unit',l.unit,'reps',l.reps,'seconds',l.seconds,'isPr',l.is_pr) ORDER BY l.position,l.set_no) FROM workout_set_logs l JOIN exercises e ON e.id=l.exercise_id WHERE l.session_id=ws.id),'[]'::jsonb)) FROM check_ins c JOIN workout_sessions ws ON ws.check_in_ids @> ARRAY[c.id] AND ws.user_id=c.user_id WHERE c.id=_check_in_id AND ws.logged_at IS NOT NULL AND is_group_member(c.group_id,auth.uid()) AND safety_visible(c.user_id) LIMIT 1 $$;